1: //! Breaking a duration in milliseconds into whole hours, minutes and seconds.
2: 
3: /// A duration split into its parts. Each field is the whole count of that unit
4: /// *after* the larger units have been taken out, so `minutes` is always 0..60
5: /// and `seconds` is always 0..60.
6: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
7: pub struct Parts {
8:     pub hours: u64,
9:     pub minutes: u64,
10:     pub seconds: u64,
11: }
12: 
13: const SEC: u64 = 1_000;
14: const MIN: u64 = 60 * SEC;
15: const HOUR: u64 = 60 * MIN;
16: 
17: /// Split `ms` into whole hours, minutes and seconds.
18: pub fn split(ms: u64) -> Parts {
19:     Parts {
20:         hours: ms / HOUR,
21:         minutes: ms / MIN,
22:         seconds: (ms / SEC) % 60,
23:     }
24: }

