1: // Contract test for the duration formatter. FROZEN: a solver must not modify
2: // this file.
3: #[path = "format.rs"]
4: mod format;
5: 
6: use format::split::{split, Parts};
7: use format::{label, render, render_unreduced};
8: 
9: // --- the reported symptom: the summary line ---
10: 
11: #[test]
12: fn a_summary_line_past_an_hour_shows_the_minutes_within_that_hour() {
13:     // 1h 25m 30s. The minute field is minutes-within-the-hour, not total minutes.
14:     assert_eq!(render(5_130_000), "1:25:30");
15: }
16: 
17: #[test]
18: fn a_summary_line_past_two_hours_shows_the_minutes_within_that_hour() {
19:     // 2h 45m 09s.
20:     assert_eq!(render(9_909_000), "2:45:09");
21: }
22: 
23: #[test]
24: fn a_summary_line_under_an_hour_is_unaffected() {
25:     // 0h 42m 07s.
26:     assert_eq!(render(2_527_000), "0:42:07");
27: }
28: 
29: // --- the same defect, seen through the short label ---
30: 
31: #[test]
32: fn a_short_label_past_an_hour_shows_the_minutes_within_that_hour() {
33:     assert_eq!(label(5_130_000), "1h 25m");
34: }
35: 
36: // --- the invariant the split itself must hold ---
37: 
38: #[test]
39: fn a_split_never_lets_a_field_overflow_its_unit() {
40:     for ms in [0u64, 999, 59_000, 60_000, 3_599_000, 3_600_000, 5_130_000, 86_399_000] {
41:         let p = split(ms);
42:         assert!(p.minutes < 60, "minutes overflowed for {ms}ms: {p:?}");
43:         assert!(p.seconds < 60, "seconds overflowed for {ms}ms: {p:?}");
44:     }
45: }
46: 
47: #[test]
48: fn a_split_still_totals_back_to_the_original() {
49:     for ms in [0u64, 59_000, 3_600_000, 5_130_000, 9_909_000] {
50:         let Parts {
51:             hours,
52:             minutes,
53:             seconds,
54:         } = split(ms);
55:         assert_eq!(
56:             hours * 3_600_000 + minutes * 60_000 + seconds * 1_000,
57:             ms / 1_000 * 1_000,
58:             "parts do not total back for {ms}ms"
59:         );
60:     }
61: }
62: 
